var _danBlindsMaxStops = 8;

function _danBlindsHexToRgb(hex) {
    var color = (hex || "#000000").replace("#", "");
    while (color.length < 6) {
        color += "0";
    }
    return [
        parseInt(color.slice(0, 2), 16) / 255,
        parseInt(color.slice(2, 4), 16) / 255,
        parseInt(color.slice(4, 6), 16) / 255
    ];
}

function _danBlindsBuildStops(stops) {
    var base = stops && stops.length ? stops.slice(0, _danBlindsMaxStops) : ["#FF9FFC", "#5227FF"];
    if (base.length === 1) {
        base.push(base[0]);
    }
    while (base.length < _danBlindsMaxStops) {
        base.push(base[base.length - 1]);
    }

    var arr = [];
    for (var i = 0; i < _danBlindsMaxStops; i += 1) {
        arr.push(_danBlindsHexToRgb(base[i]));
    }

    return {
        arr: arr,
        count: Math.max(2, Math.min(_danBlindsMaxStops, stops ? stops.length : 2))
    };
}

var _danBlindsVert = [
    "attribute vec2 position;",
    "attribute vec2 uv;",
    "varying vec2 vUv;",
    "void main(){vUv=uv;gl_Position=vec4(position,0.0,1.0);}"
].join("\n");

var _danBlindsFrag = [
    "#ifdef GL_ES",
    "precision mediump float;",
    "#endif",
    "uniform vec3 uViewport;",
    "uniform vec2 uPointer;",
    "uniform float uElapsed;",
    "uniform float uRotation;",
    "uniform float uGrain;",
    "uniform float uStripeCount;",
    "uniform float uLightRadius;",
    "uniform float uLightFalloff;",
    "uniform float uLightStrength;",
    "uniform float uReflect;",
    "uniform float uWarp;",
    "uniform float uStripeInvert;",
    "uniform vec3 uStop0;",
    "uniform vec3 uStop1;",
    "uniform vec3 uStop2;",
    "uniform vec3 uStop3;",
    "uniform vec3 uStop4;",
    "uniform vec3 uStop5;",
    "uniform vec3 uStop6;",
    "uniform vec3 uStop7;",
    "uniform int uStopCount;",
    "varying vec2 vUv;",
    "float hash21(vec2 co){return fract(sin(dot(co,vec2(27.619,57.583)))*23758.2137);}",
    "vec2 rot(vec2 p,float a){float c=cos(a);float s=sin(a);return vec2(c*p.x-s*p.y,s*p.x+c*p.y);}",
    "vec3 fetchStop(int i){",
    "  if(i<=0)return uStop0;if(i==1)return uStop1;if(i==2)return uStop2;if(i==3)return uStop3;",
    "  if(i==4)return uStop4;if(i==5)return uStop5;if(i==6)return uStop6;return uStop7;",
    "}",
    "vec3 sampleGradient(float t){",
    "  float tt=clamp(t,0.0,1.0);",
    "  int count=uStopCount;if(count<2)count=2;",
    "  float scaled=tt*float(count-1);",
    "  int idx=int(floor(scaled));",
    "  float f=fract(scaled);",
    "  if(idx>=count-1){idx=count-2;f=1.0;}",
    "  return mix(fetchStop(idx),fetchStop(idx+1),f);",
    "}",
    "void render(out vec4 fragColor,in vec2 fragCoord){",
    "  vec2 uv0=fragCoord.xy/uViewport.xy;",
    "  float aspect=uViewport.x/uViewport.y;",
    "  vec2 p=uv0*2.0-1.0;p.x*=aspect;",
    "  vec2 pr=rot(p,uRotation);pr.x/=aspect;",
    "  vec2 uv=pr*0.5+0.5;vec2 uvMod=uv;",
    "  if(uWarp>0.0){float a=uvMod.y*6.0;float b=uvMod.x*6.0;float w=0.01*uWarp;uvMod.x+=sin(a)*w;uvMod.y+=cos(b)*w;}",
    "  float t=uvMod.x;",
    "  if(uReflect>0.5){t=1.0-abs(1.0-2.0*fract(t));}",
    "  vec3 base=sampleGradient(t);",
    "  vec2 offset=uPointer/uViewport.xy;",
    "  float d=length(uv0-offset);",
    "  float r=max(uLightRadius,1e-4);",
    "  float spot=(1.0-2.0*pow(d/r,uLightFalloff))*uLightStrength;",
    "  float stripe=fract(uvMod.x*max(uStripeCount,1.0));",
    "  if(uStripeInvert>0.5)stripe=1.0-stripe;",
    "  vec3 col=base+vec3(spot)-vec3(stripe);",
    "  col+=(hash21(gl_FragCoord.xy+uElapsed)-0.5)*uGrain;",
    "  fragColor=vec4(col,1.0);",
    "}",
    "void main(){vec4 color;render(color,vUv*uViewport.xy);gl_FragColor=color;}"
].join("\n");

function dancepad_blinds(){document.querySelectorAll(".dan-blinds").forEach(function(element){if(element._danBlindsCtx){try{if(element._danBlindsCtx.raf){cancelAnimationFrame(element._danBlindsCtx.raf)}
if(element._danBlindsCtx.ro){element._danBlindsCtx.ro.disconnect()}
if(element._danBlindsCtx.onPtr){element._danBlindsCtx.canvas.removeEventListener("pointermove",element._danBlindsCtx.onPtr)}}catch(e){}
element._danBlindsCtx=null}
var canvas=element.querySelector(".dan-blinds__canvas");if(!canvas){return}
var blendMode=element.getAttribute("data-blend");if(blendMode){canvas.style.mixBlendMode=blendMode}
var gl=canvas.getContext("webgl",{alpha:!0,antialias:!0,premultipliedAlpha:!1});if(!gl){element.removeAttribute("data-flickering");return}
function compile(source,type){var shader=gl.createShader(type);gl.shaderSource(shader,source);gl.compileShader(shader);if(!gl.getShaderParameter(shader,gl.COMPILE_STATUS)){gl.deleteShader(shader);return null}
return shader}
var vertexShader=compile(_danBlindsVert,gl.VERTEX_SHADER);var fragmentShader=compile(_danBlindsFrag,gl.FRAGMENT_SHADER);if(!vertexShader||!fragmentShader){element.removeAttribute("data-flickering");return}
var program=gl.createProgram();gl.attachShader(program,vertexShader);gl.attachShader(program,fragmentShader);gl.linkProgram(program);if(!gl.getProgramParameter(program,gl.LINK_STATUS)){element.removeAttribute("data-flickering");return}
gl.useProgram(program);var posLoc=gl.getAttribLocation(program,"position");var uvLoc=gl.getAttribLocation(program,"uv");var positionBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,positionBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([-1,-1,3,-1,-1,3]),gl.STATIC_DRAW);gl.enableVertexAttribArray(posLoc);gl.vertexAttribPointer(posLoc,2,gl.FLOAT,!1,0,0);var uvBuffer=gl.createBuffer();gl.bindBuffer(gl.ARRAY_BUFFER,uvBuffer);gl.bufferData(gl.ARRAY_BUFFER,new Float32Array([0,0,2,0,0,2]),gl.STATIC_DRAW);gl.enableVertexAttribArray(uvLoc);gl.vertexAttribPointer(uvLoc,2,gl.FLOAT,!1,0,0);var colorStops=(element.getAttribute("data-colors")||"#FF9FFC|#5227FF").split("|");var preparedStops=_danBlindsBuildStops(colorStops);var angle=parseFloat(element.getAttribute("data-angle")||0);var noise=parseFloat(element.getAttribute("data-noise")||0.3);var blindCount=parseInt(element.getAttribute("data-blind-count")||16,10);var blindMinWidth=parseInt(element.getAttribute("data-blind-min-width")||60,10);var mirror=element.getAttribute("data-mirror")==="1"?1:0;var shine=element.getAttribute("data-shine")==="right"?1:0;var distort=parseFloat(element.getAttribute("data-distort")||0);var spotlightRadius=parseFloat(element.getAttribute("data-spot-radius")||0.5);var spotlightSoftness=parseFloat(element.getAttribute("data-spot-softness")||1);var spotlightOpacity=parseFloat(element.getAttribute("data-spot-opacity")||1);var mouseDampening=parseFloat(element.getAttribute("data-mouse-damp")||0.15);var uViewport=gl.getUniformLocation(program,"uViewport");var uPointer=gl.getUniformLocation(program,"uPointer");var uElapsed=gl.getUniformLocation(program,"uElapsed");var uRotation=gl.getUniformLocation(program,"uRotation");var uGrain=gl.getUniformLocation(program,"uGrain");var uStripeCount=gl.getUniformLocation(program,"uStripeCount");var uLightRadius=gl.getUniformLocation(program,"uLightRadius");var uLightFalloff=gl.getUniformLocation(program,"uLightFalloff");var uLightStrength=gl.getUniformLocation(program,"uLightStrength");var uReflect=gl.getUniformLocation(program,"uReflect");var uWarp=gl.getUniformLocation(program,"uWarp");var uStripeInvert=gl.getUniformLocation(program,"uStripeInvert");var uStopCount=gl.getUniformLocation(program,"uStopCount");var uStops=[];for(var i=0;i<_danBlindsMaxStops;i+=1){uStops.push(gl.getUniformLocation(program,"uStop"+i))}
gl.uniform1f(uRotation,angle*Math.PI/180);gl.uniform1f(uGrain,noise);gl.uniform1f(uReflect,mirror);gl.uniform1f(uStripeInvert,shine);gl.uniform1f(uWarp,distort);gl.uniform1f(uLightRadius,spotlightRadius);gl.uniform1f(uLightFalloff,spotlightSoftness);gl.uniform1f(uLightStrength,spotlightOpacity);gl.uniform1i(uStopCount,preparedStops.count);for(var j=0;j<_danBlindsMaxStops;j+=1){gl.uniform3fv(uStops[j],preparedStops.arr[j])}
var target=[0,0];var current=[0,0];var lastTime=0;var dpr=window.devicePixelRatio||1;var firstResize=!0;function resize(){var rect=element.getBoundingClientRect();if(rect.width<1||rect.height<1){return}
var width=Math.round(rect.width*dpr);var height=Math.round(rect.height*dpr);canvas.width=width;canvas.height=height;gl.viewport(0,0,width,height);gl.uniform3f(uViewport,width,height,1);if(blindMinWidth>0){var maxCount=Math.max(1,Math.floor(rect.width/blindMinWidth));gl.uniform1f(uStripeCount,Math.max(1,blindCount?Math.min(blindCount,maxCount):maxCount))}else{gl.uniform1f(uStripeCount,Math.max(1,blindCount))}
if(firstResize){firstResize=!1;var cx=width/2;var cy=height/2;current=[cx,cy];target=[cx,cy];gl.uniform2f(uPointer,cx,cy)}}
resize();var resizeObserver=new ResizeObserver(function(){resize()});resizeObserver.observe(element);var onPointerMove=function(event){var rect=canvas.getBoundingClientRect();var x=(event.clientX-rect.left)*dpr;var y=(rect.height-(event.clientY-rect.top))*dpr;target=[x,y];if(mouseDampening<=0){current=[x,y];gl.uniform2f(uPointer,x,y)}};canvas.addEventListener("pointermove",onPointerMove);var raf;function loop(time){raf=requestAnimationFrame(loop);gl.uniform1f(uElapsed,time*0.001);if(mouseDampening>0){if(!lastTime){lastTime=time}
var delta=(time-lastTime)/1000;lastTime=time;var smooth=Math.max(1e-4,mouseDampening);var blend=1-Math.exp(-delta/smooth);if(blend>1){blend=1}
current[0]+=(target[0]-current[0])*blend;current[1]+=(target[1]-current[1])*blend;gl.uniform2f(uPointer,current[0],current[1])}else{lastTime=time}
gl.drawArrays(gl.TRIANGLES,0,3)}
raf=requestAnimationFrame(loop);element._danBlindsCtx={gl:gl,raf:raf,ro:resizeObserver,canvas:canvas,onPtr:onPointerMove,program:program};element.removeAttribute("data-flickering")})}
window.dancepad_blinds=dancepad_blinds;if(document.readyState==="loading"){document.addEventListener("DOMContentLoaded",dancepad_blinds)}else{dancepad_blinds()}